-- CF-96: versioned graphs extend the existing automation engine.
CREATE TABLE workflows (id BIGSERIAL PRIMARY KEY, uuid UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE, organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 200),draft JSONB NOT NULL,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),published_version INTEGER,enabled BOOLEAN NOT NULL DEFAULT false,created_by BIGINT NOT NULL REFERENCES users(id),next_schedule_at TIMESTAMPTZ NOT NULL DEFAULT now(),schedule_cursor BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(organization_id,id));
CREATE INDEX idx_workflows_org ON workflows(organization_id);
CREATE TRIGGER trg_workflows_updated BEFORE UPDATE ON workflows FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE workflow_versions (id BIGSERIAL PRIMARY KEY, uuid UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE, organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,workflow_id BIGINT NOT NULL,version INTEGER NOT NULL,graph JSONB NOT NULL,trigger_event TEXT NOT NULL,schedule_minutes INTEGER NOT NULL DEFAULT 0 CHECK(schedule_minutes BETWEEN 0 AND 525600),created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(organization_id,id),FOREIGN KEY(organization_id,workflow_id) REFERENCES workflows(organization_id,id) ON DELETE CASCADE,UNIQUE(organization_id,workflow_id,version));
CREATE INDEX idx_workflow_versions_org ON workflow_versions(organization_id);
CREATE TRIGGER trg_workflow_versions_updated BEFORE UPDATE ON workflow_versions FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE workflow_runs (id BIGSERIAL PRIMARY KEY, uuid UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE, organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,workflow_id BIGINT NOT NULL,version_id BIGINT NOT NULL,event_id UUID NOT NULL,conversation_uuid UUID NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','waiting','succeeded','failed','blocked')),node_id TEXT NOT NULL,step_index INTEGER NOT NULL DEFAULT 0 CHECK(step_index BETWEEN 0 AND 256),trace JSONB NOT NULL DEFAULT '[]',error TEXT NOT NULL DEFAULT '',due_at TIMESTAMPTZ NOT NULL DEFAULT now(),lease_until TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(organization_id,id),FOREIGN KEY(organization_id,workflow_id) REFERENCES workflows(organization_id,id) ON DELETE CASCADE,FOREIGN KEY(organization_id,version_id) REFERENCES workflow_versions(organization_id,id) ON DELETE CASCADE,FOREIGN KEY(organization_id,conversation_uuid) REFERENCES conversations(organization_id,uuid) ON DELETE CASCADE,UNIQUE(organization_id,workflow_id,event_id,conversation_uuid));
CREATE INDEX idx_workflow_runs_org ON workflow_runs(organization_id,created_at DESC);
CREATE TRIGGER trg_workflow_runs_updated BEFORE UPDATE ON workflow_runs FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TABLE workflow_steps (id BIGSERIAL PRIMARY KEY, uuid UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE, organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,run_id BIGINT NOT NULL,step_index INTEGER NOT NULL,node_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('started','succeeded','failed','uncertain')),output JSONB NOT NULL DEFAULT '{}',error TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(organization_id,id),FOREIGN KEY(organization_id,run_id) REFERENCES workflow_runs(organization_id,id) ON DELETE CASCADE,UNIQUE(organization_id,run_id,step_index));
CREATE INDEX idx_workflow_steps_org ON workflow_steps(organization_id);
CREATE TRIGGER trg_workflow_steps_updated BEFORE UPDATE ON workflow_steps FOR EACH ROW EXECUTE FUNCTION set_updated_at();
ALTER TABLE workflows ADD CONSTRAINT fk_workflow_published FOREIGN KEY(organization_id,id,published_version) REFERENCES workflow_versions(organization_id,workflow_id,version) DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX idx_workflow_runs_due ON workflow_runs(due_at) WHERE status IN ('pending','waiting','running');
INSERT INTO billing_features(key,kind,label_tr,label_en,unit,aggregation,period) VALUES ('workflows.enabled','boolean','Görsel iş akışları','Visual workflows','','none','none'),('workflows.count','limit','İş akışı sayısı','Workflow count','workflow','gauge','none'),('workflows.runs_daily','limit','Günlük iş akışı çalıştırma','Daily workflow runs','run','gauge','none') ON CONFLICT(key) DO NOTHING;
